"""Partitive "of" detector (layer 15 MLP, down_proj component 69).

What it does: this component writes into the residual stream a direction that
promotes demonstrative/pronoun continuations ("these", "those", "them", "这些")
right after an "of". It is active on the preposition "of" (and its Romance and
Dutch cousins "de", "van", "di", "der"), and most strongly when "of" is partitive,
i.e. after a quantifier or fraction word: "many of", "some of", "most of",
"each of", "percent of", "one of". It is weak after idiomatic "of" phrases such as
"instance of", "out of", "because of", "member of", "kind of". Everywhere else it is
silent, apart from a slight negative offset on common English prepositions.

The program predicts that activation from the word before "of"; it has no state.
"""
from collections.abc import Mapping

READS: tuple = ()

OF_TOKENS = {" of", " OF", " Of", "of"}
FOREIGN_OF = {" de", " van", " di", " der", " của"}
PREPOSITIONS = {" in", " for", " on", " from", " by", " with", " into", " to", " at"}

# Words after which "of" is partitive or quantity-like: "many of", "percent of".
QUANTITY_WORDS = {
    "many", "some", "all", "most", "each", "any", "both", "none", "rest", "half",
    "two", "majority", "portion", "portions", "fraction", "percent", "percentage",
    "%", "proportion", "pair", "subset", "much", "several", "either", "one", "few",
    "snippet",
}
# Words whose "of" is a fixed idiom rather than a partitive: "instance of", "out of".
IDIOM_WORDS = {
    "instance", "out", "because", "terms", "place", "member", "kind", "sort",
    "capable", "way", "lack", "history",
}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    if tok in FOREIGN_OF:
        return carry, 1.0
    if tok in PREPOSITIONS:
        return carry, -0.3
    if tok not in OF_TOKENS:
        return carry, 0.0
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if prev in QUANTITY_WORDS:
        return carry, 4.5
    if prev in IDIOM_WORDS:
        return carry, 0.5
    return carry, 2.3

"""Conditional-mood neuron: layer 15, MLP hidden unit 74 (the component reads
almost only that unit).

It dips negative on the auxiliary that marks a hypothetical or conditional
verb: English "would" (strongest), "could", "might" and "'d", and the
matching words in other languages (German würde/wäre/könnte, Spanish sería,
French serait/pourrait, Dutch zou, Russian бы, ...). The dip is
a typical size per word. It is deeper after a first- or second-person subject
("I would", "you could") and shallower after a third-person one ("he would").
The verb straight after such a marker ("would BE", "would HAVE", "would NOT")
carries a weaker copy, about two thirds of the marker's dip. Everywhere else
the neuron is near zero, so the program predicts 0.
"""
READS = ()

# Typical activation on each conditional marker (negative: the neuron dips).
CONDITIONAL = {
    " would": -11.0, " Would": -17.0, "would": -12.0, "'d": -12.0, "’d": -12.0,
    " could": -6.0, " Could": -6.0, " might": -4.0, " Might": -6.0,
    " wäre": -17.0, " würde": -10.0, " könnte": -11.0, " hätte": -9.0,
    " sería": -14.0, " podría": -4.0, " serait": -13.0, " pourrait": -6.0,
    " zou": -21.0, " бы": -4.0, " skulle": -4.5,
}
FIRST_SECOND_PERSON = {" I", " you", " You", " we", " We", "I"}
THIRD_PERSON = {" he", " she", " He", " She", " they", " They"}
# Verbs that usually come straight after a marker.
AFTER_MARKER = {" be", " have", " not", " been", " love", " like", " want", " do"}
FOLLOW_SHARE = 0.65  # the verb after a marker carries this share of its dip


def marker_value(tokens, i):
    """Predicted activation at position i if it is a conditional marker, else 0."""
    word = tokens[i]
    if word not in CONDITIONAL:
        return 0.0
    value = CONDITIONAL[word]
    if i > 0 and tokens[i - 1] in FIRST_SECOND_PERSON:
        value *= 1.5
    elif i > 0 and tokens[i - 1] in THIRD_PERSON:
        value *= 0.7
    return value


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    t = len(tokens) - 1
    # Only look back within the same document.
    if t >= 1 and prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return carry, marker_value(tokens, t)
    if t >= 1 and tokens[t] in AFTER_MARKER:
        return carry, FOLLOW_SHARE * marker_value(tokens, t - 1)
    return carry, marker_value(tokens, t)

"""Token-class program for one MLP down-projection component (layer 15, component 75).

The component reads the MLP's hidden units and writes a small signed signal into the
residual stream. Its activation is mostly driven by the current token, and this program
predicts it from a few word classes a reader can check:

- the opening of a JSON object, '{"': strongly positive (about 4);
- logical conclusion words, Thus / Therefore / Hence / So: positive (about 2.5);
- agent tool-call syntax (<tool_call>, arguments, the '",' and '\\"' of JSON strings): about 1.2;
- opening brackets '(' '[' and quote-opening ' "': about 0.5;
- other punctuation and symbol tokens: a small positive value (0.15);
- programming and shell vocabulary (java, git, printf, ...): negative (about -0.6);
- everything else: 0.

Token identity explains only a few percent of the variance (the best token-table ceiling we
measured is about 8%), so this is a coarse description. It captures the sign and the main
peaks, not the bulk of the variance.
"""

READS = ()

# Logical conclusion words that open a clause: "Thus, ...", "So the ...".
CONCLUSIONS = {"thus", "therefore", "hence", "so", "因此", "所以"}

# Tool-call and JSON syntax from agent transcripts.
TOOL_SYNTAX = {"<tool_call>", "<tool_response>", "arguments", '",', '\\"'}

# Programming-language and shell vocabulary, which pushes the activation below zero.
CODE_TERMS = {"java", "python", "printf", "println", "git", "grep", "javascript", "php", "sql", "bash"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    if '{"' in tok:  # the opening of a JSON object: '{"' or ' {"'
        value = 4.0
    elif word.lower() in CONCLUSIONS:
        value = 2.5
    elif word in TOOL_SYNTAX:
        value = 1.2
    elif word in {"(", "[", "([", "((", "({"}:  # bare opening brackets
        value = 0.5
    elif tok == ' "':
        value = 0.6
    elif word.lower() in CODE_TERMS:
        value = -0.6
    elif word and not any(ch.isalnum() for ch in word):  # other punctuation and symbols
        value = 0.15
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 91: a weak, diffuse feature.

What it does (as a rule): it is mostly near zero, but it is pushed up
  - on the word "to" when it starts an infinitive ("need to", "want to",
    "easy to", "ways to"), a bit less for other "to", and not for prepositional
    "to" ("due to", "prior to", "according to");
  - on "make" and its forms (make, makes, made, making), the strongest trigger;
  - on the word "assistant" (and "user") right after a chat-role marker
    <|im_start|>;
  - a little on modal and action verbs (can, could, must, should, do, need,
    want, know, use, take, keep, said, see);
and pushed down on subject pronouns in running text (they, he, she, you, we,
I, it), most of all right after a relative word ("which they", "that he").

The weights are least-squares fits on 8k training rows; they explain only a
few percent of its variance. Most of its variance is token-by-token detail
that no short word rule captures.
"""

# Words that take an infinitive "to" after them.
INFINITIVE_LEADS = {
    "need", "needs", "needed", "want", "wanted", "have", "has", "had", "able",
    "ready", "easy", "difficult", "enough", "important", "required", "likely",
    "time", "way", "like", "possible", "how", "what", "which", "that", "things",
    "places", "options", "thing",
}
# Words that take a prepositional "to" after them.
PREPOSITIONAL_LEADS = {
    "due", "according", "prior", "related", "compared", "respect", "addition",
    "leading", "close", "connected", "applied", "subject", "referred", "similar",
    "equal", "up", "back", "lead", "set",
}
MAKE_FORMS = {"make", "makes", "made", "making"}
ACTION_VERBS = {
    "can", "could", "must", "should", "do", "need", "want", "know", "use",
    "used", "take", "took", "keep", "said", "see",
}
SUBJECT_PRONOUNS = {"they", "she", "he", "you", "we", "it", "i"}
RELATIVE_WORDS = {"which", "that", "whom", "who"}

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    word = tokens[-1].strip().lower()
    prev = tokens[-2].strip().lower() if len(tokens) > 1 else ""
    spaced = tokens[-1].startswith(" ")
    if word == "to":
        if prev in INFINITIVE_LEADS:
            value = 1.4
        elif prev in PREPOSITIONAL_LEADS:
            value = 0.0
        else:
            value = 0.6
    elif word in MAKE_FORMS:
        value = 2.3
    elif word == "assistant" and prev == "<|im_start|>":
        value = 2.9
    elif word == "user" and prev == "<|im_start|>":
        value = 0.5
    elif word in ACTION_VERBS:
        value = 0.6
    elif word in SUBJECT_PRONOUNS and spaced:
        value = -1.1 if prev in RELATIVE_WORDS else -0.3
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 95: a diffuse, context-driven signal.

Its activation is large in both signs (std 0.49, spikes to +18 and -31), but no simple
token rule explains it: token identity explains about 1-2% of the variance, and a linear
readout of the whole residual stream only about 17%. What small, consistent structure exists:
  - negative on "update" words and "+=" (its output, read through the unembedding, promotes
    "update" when the activation is negative);
  - negative on time-period words ("day", "week", "month", "year", "every", "daily");
  - slightly positive on "since", month names, and null/nil/err;
  - slightly negative on the connectives "therefore", "thus", "so".
This program predicts each group's mean activation, and 0 for every other token.
"""

READS = ()

UPDATE_WORDS = {"update", "updates", "updated", "updating", "+="}
TIME_WORDS = {"day", "days", "week", "weeks", "month", "months", "year", "years", "today",
              "daily", "weekly", "monthly", "yearly", "annual", "every"}
MONTHS = {"january", "february", "march", "april", "may", "june", "july", "august",
          "september", "october", "november", "december"}
NULLS = {"nil", "null", "none", "err", "error"}
CONNECTIVES = {"therefore", "thus", "so"}

GROUP_MEANS = [
    (UPDATE_WORDS, -0.6),
    (TIME_WORDS, -0.26),
    ({"since"} | MONTHS | NULLS, 0.2),
    (CONNECTIVES, -0.12),
]


def step(carry, prefix, upstream):
    """Activation at the newest token: its word group's mean, else 0."""
    word = prefix.token_strings[-1].strip().lower()
    for words, mean in GROUP_MEANS:
        if word in words:
            return carry, mean
    return carry, 0.0

"""Predicts the activation of component 98 of layer 15's MLP down projection.

That component is almost entirely MLP hidden unit 98 of layer 15 (it carries about two thirds
of the component's variance), so this is a rule sketch of when that unit is strongly on or off.
It reads only the current token and the one or two before it, in the same document.

What it responds to, from the data (values are the typical activation for each case):
- Punctuation right after a single capital letter, an initial or abbreviation ("N.Y.", "B.C.",
  "J. Smith"): strongly positive, about 4 for a period, 2.3 for a space, 2.8 for a dash.
- A period right after a capitalised word ("Inc.", "Smith."): about 1.
- Punctuation after a digit: positive, most after a standalone number ("3.14", "9:30", "1, 2").
- A dash between two digits (phone numbers, page and ID ranges such as "617-236"): negative, about -1.5.
- Other digits after a digit: slightly negative.
- A dash inside a lowercase word (a word split across lines, compounds): about 1.
- " and" / " or" after a lowercase word: about 0.5. A newline after a lowercase word: about 0.6.
- " (" after a lowercase word: about -0.6.
Everything else predicts 0. Measured on eval: variance explained 0.035, r 0.20.
Most of the component's variance is in rare large values that these rules do not reach.
"""
import re

READS = ()


def _back(prefix, k):
    """The token k places before the current one, or None before its document starts."""
    i = len(prefix.token_strings) - 1 - k
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return None
    return prefix.token_strings[i]


def _kind(s):
    if s is None:
        return "start"
    if s.strip() == "":
        return "space"
    if re.fullmatch(r"[A-Z]", s.strip()):
        return "initial"
    if re.fullmatch(r"[0-9]", s.strip()):
        return "digit"
    if re.fullmatch(r"[a-z]+", s.strip()):
        return "lower"
    if re.fullmatch(r"[A-Z][a-z]+", s.strip()):
        return "capital"
    return "other"


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip()
    k1 = _kind(_back(prefix, 1))
    k2 = _kind(_back(prefix, 2))
    if k1 == "initial":
        return None, {".": 4.0, "-": 2.8, "–": 2.8, " ": 2.3}.get(raw, 0.0)
    if k1 == "digit":
        if cur in ("-", "–"):
            return None, -1.5 if k2 == "digit" else 0.0
        if cur == ".":
            return None, 2.0 if k2 == "space" else 1.6
        if cur == ",":
            return None, 2.2 if k2 == "space" else 1.2
        if cur == ":":
            return None, 2.0
        if cur.isdigit():
            return None, -0.2
        return None, 0.0
    if k1 == "lower":
        if cur in ("-", "–"):
            return None, 1.1
        if raw in (" and", " or"):
            return None, 0.5
        if raw == "\n":
            return None, 0.6
        if raw == " (":
            return None, -0.6
    if k1 == "capital" and raw == ".":
        return None, 1.0
    return None, 0.0

"""Layer 15, MLP down_proj, component 110 of Qwen3-1.7B.

What the component is: one rank-one piece of down_proj. Its input direction is dominated
by MLP hidden unit 110 of layer 15 (V weight 0.78 on that unit), so its activation is a
signed number, near 0 most of the time, with rare large spikes (mostly negative, down to
about -13; positive up to about +7).

What this program says: read from the current word alone, the component has a small
tendency:
  - negative on plural nouns that head "the main X of/to ..." lists (aspects, features,
    questions, advantages, criteria, topics), on partitive lead-ins that take "of" next
    (one, most, main, variety), and on tool-call JSON keys (command, name);
  - positive on code and markup openers (``` fences, {", <think>, _editor, cat, grep)
    and on determiners that take a bare noun next (these, following, each, few, both);
  - otherwise about its mean, 0.01.
These word groups explain well under 1% of its variance on eval. The same word can be
strongly negative in one place and positive in another, and whole documents, token
classes and next-token predictability add little. A per-word lookup table reaches roughly
3% on training text; it is not a readable explanation, so it is left out.

The program keeps no state: each position is judged by its own newest token.
"""

READS = ()

NOUN_LISTS = {
    "aspects", "aspect", "features", "feature", "questions", "services", "properties",
    "characteristics", "tips", "advantages", "benefits", "criteria", "topics", "goals",
    "reasons", "rules", "issues", "parameters", "arguments", "tests", "options",
}
TOOL_KEYS = {"command", "name", "view", "ask", "path", "bash", "arguments"}
PARTITIVE_LEADS = {
    "one", "One", "most", "main", "particular", "specifically", "specific", "variety",
    "many", "Many",
}
CODE_MARKUP = {
    "```", '{"', "<think>", "_editor", "cat", "grep", "snippet", "Python", "interpreter", "Edit",
}
DETERMINERS = {
    "these", "following", "each", "few", "both", "other", "only", "certain", "various", "several",
}

NOUN_LIST_VALUE = -0.44
PARTITIVE_VALUE = -0.17
CODE_VALUE = 0.35
DETERMINER_VALUE = 0.18
REST = 0.01


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" ")
    if word in NOUN_LISTS or word in TOOL_KEYS:
        value = NOUN_LIST_VALUE
    elif word in PARTITIVE_LEADS:
        value = PARTITIVE_VALUE
    elif word in CODE_MARKUP:
        value = CODE_VALUE
    elif word in DETERMINERS:
        value = DETERMINER_VALUE
    else:
        value = REST
    return carry, float(value)

"""Layer 15, MLP unit 113: down_proj component 113, as a small rule set.

What the component does: it is one rank-one slice of layer 15's MLP output. Its
activation is heavy-tailed (mostly about -0.05, with rare swings of +/-10 to +/-50),
and most of its variance sits in ordinary text, not in any one token class. Token
identity alone predicts almost none of it. The part that can be read is about
dates and years written as digits:

- The last digit of a 4-digit year starting 19 or 20 is high inside an author-year
  citation, e.g. "(Lin et al., 201[2])": about +1.2 on average.
- The same digit is low inside a date, e.g. "Aug 21, 200[6]" or "08/01/201[4]":
  about -1.2 on average.
- Other years sit slightly above the baseline (+0.24).
- Tokens 5 to 9 places after a month name (inside a date) lean negative, about -0.3.
- Dashes and no-break spaces, about -0.3; later pieces of a capitalised word split
  over several tokens (the "iday" of "Holliday"), about -0.12.
- Everything else takes the baseline, -0.05.

The program keeps only the last 16 tokens of the current document, and the
month distance, in its carry. It never looks at later tokens.
"""

READS = ()

BASELINE = -0.05
MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
KEEP = 16


def is_digit(s):
    return len(s) == 1 and s.isdigit()


def year_digit_value(recent):
    """Value for a token that would be the 4th digit of a 19xx or 20xx year."""
    if len(recent) < 3 or not all(is_digit(s) for s in recent[-3:]):
        return None
    if len(recent) >= 4 and is_digit(recent[-4]):
        return None  # the number starts earlier than the year
    if recent[-3] + recent[-2] not in ("19", "20"):
        return None
    text = "".join(recent[-12:-3])  # text just before the year
    if "(" in text[-8:] or "et al" in text[-14:]:
        return 1.2  # author-year citation
    if any(m in text[-14:] for m in MONTHS) or "/" in text[-6:]:
        return -1.2  # date
    return 0.24


def name_piece(tok, recent):
    """True for a later piece of a capitalised word split over several tokens."""
    if not tok.isalpha() or tok.startswith(" "):
        return False
    k = len(recent)
    while k > 0 and recent[k - 1].isalpha() and not recent[k - 1].startswith(" "):
        k -= 1
    if k == len(recent):
        return False
    return recent[k].lstrip(" ")[:1].isupper()


def step(carry, prefix, upstream):
    """Activation at the newest token, from the tokens so far in its document."""
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        recent, since_month = (), 99
    else:
        _, recent, since_month = carry
    since_month = 0 if tok.strip() in MONTHS else since_month + 1
    value = None
    if is_digit(tok):
        value = year_digit_value(recent)
    elif name_piece(tok, recent):
        value = -0.12
    elif tok.strip() in ("-", "\xa0"):
        value = -0.3
    elif 5 <= since_month <= 9:
        value = -0.3
    if value is None:
        value = BASELINE
    return (doc, (recent + (tok,))[-KEEP:], since_month), float(value)

"""Question-opening detector for layers.15.mlp.down_proj:125.

The component is negative on the words that open an inverted question
("What IS ...", "How DO you ...", "Are YOU ...") and positive on the question
mark that ends a question.
"""
READS = ()

WH = {"what", "how", "who", "why", "when", "where", "which"}
AUX = {"is", "are", "do", "does", "did", "can", "will", "would", "was",
       "were", "has", "have", "should", "could", "am"}
SUBJ = {"you", "i", "it", "we", "they", "he", "she", "this", "that", "there"}
END = {".", "!", "?", "？", ":", ";", "", "<|im_start|>", "<|endoftext|>"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    # carry: (tokens since sentence start, first word of sentence, previous word)
    if carry is None or prefix.position == 0:
        n, first, prev = 0, "", ""
    else:
        n, first, prev = carry
    act = 0.0
    if word in ("?", "？"):
        act = 4.0
    elif n == 1 and first in WH and word in AUX:
        act = -8.0
    elif n == 1 and first in AUX and word in SUBJ:
        act = -8.0
    elif n == 2 and first in WH and prev in AUX and word in SUBJ:
        act = -7.0
    if word in END or "\n" in raw:
        carry = (0, "", word)
    else:
        carry = (n + 1, first if n else word, word)
    return carry, act

"""Layer 15 MLP, down_proj component 126: a causative-verb detector.

The component is strongly negative on verbs of making, enabling or affecting
something ("provide", "help", "make", "determine", "ensure", "cause", "keep",
"give"). It is more mildly negative on any other verb right after "to" or a
modal ("to improve", "can affect"), and weakly negative on "for" and "by". It is
weakly positive on pronouns and modals ("it", "you", "they", "will", "can").
Everything else sits near zero. The rule reads only the current token and the
one before it, so the program is causal. It explains only about 2-3% of the
variance: the component is spread over many contexts that no short rule captures.
"""

import wordnet

READS = ()

CAUSATIVE = frozenset(
    "make help provide cause determine ensure keep give create support increase "
    "reduce improve enhance affect aid allow enable produce generate lead offer "
    "maintain promote add show bring change build protect prevent solve boost drive".split()
)
MODALS = frozenset("will can may must should could would might shall".split())
SUBJECT_WORDS = frozenset("it you they we i will can but more".split())


def _word(token):
    return token.strip().lower()


def _lemmas(word):
    return set(wordnet.base_forms(word)) | {word}


def _is_verb(word):
    return word.isalpha() and any("verb" in wordnet.parts_of_speech(w) for w in _lemmas(word))


def _is_causative(word):
    return word.isalpha() and bool(_lemmas(word) & CAUSATIVE)


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if _is_causative(word):
        value = -1.3
    elif _is_verb(word) and (prev == "to" or prev in MODALS):
        value = -0.7
    elif word in ("for", "by"):
        value = -0.25
    elif word in SUBJECT_WORDS:
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)
